create table if not exists organizations (id uuid primary key, name text not null, slug text not null unique, created_at timestamptz not null default now());
create table if not exists users (id uuid primary key, email text not null unique, name text, status text not null default 'invited', created_at timestamptz not null default now());
create table if not exists memberships (id uuid primary key, organization_id uuid not null references organizations(id), user_id uuid not null references users(id), created_at timestamptz not null default now(), unique(organization_id,user_id));
create table if not exists roles (id uuid primary key, organization_id uuid not null references organizations(id), name text not null, key text not null, unique(organization_id,key));
create table if not exists permissions (id uuid primary key, key text not null unique, description text not null);
create table if not exists role_permissions (role_id uuid not null references roles(id) on delete cascade, permission_id uuid not null references permissions(id) on delete cascade, primary key(role_id,permission_id));
create table if not exists membership_roles (membership_id uuid not null references memberships(id) on delete cascade, role_id uuid not null references roles(id) on delete cascade, primary key(membership_id,role_id));
create table if not exists companies (id uuid primary key, organization_id uuid references organizations(id), name text not null, website text, industry text, created_at timestamptz not null default now());
create table if not exists contacts (id uuid primary key, organization_id uuid references organizations(id), company_id uuid references companies(id), first_name text not null, last_name text not null, email text, phone text, created_at timestamptz not null default now());
create table if not exists leads (id uuid primary key, organization_id uuid references organizations(id), contact_id uuid references contacts(id), title text not null, status text not null default 'new', owner_id uuid references users(id), source text, created_at timestamptz not null default now());
create table if not exists pipelines (id uuid primary key, organization_id uuid references organizations(id), name text not null, created_at timestamptz not null default now());
create table if not exists pipeline_stages (id uuid primary key, pipeline_id uuid not null references pipelines(id) on delete cascade, name text not null, position integer not null, probability integer not null default 0);
create table if not exists deals (id uuid primary key, organization_id uuid references organizations(id), pipeline_id uuid references pipelines(id), stage_id uuid references pipeline_stages(id), company_id uuid references companies(id), title text not null, value numeric(14,2) not null default 0, status text not null default 'open', owner_id uuid references users(id), created_at timestamptz not null default now());
create table if not exists tasks (id uuid primary key, organization_id uuid references organizations(id), title text not null, status text not null default 'open', assignee_id uuid references users(id), due_at timestamptz, created_at timestamptz not null default now());
create table if not exists activities (id uuid primary key, organization_id uuid references organizations(id), actor_id uuid references users(id), entity_type text not null, entity_id uuid, action text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists audit_logs (id uuid primary key, organization_id uuid references organizations(id), actor_id uuid references users(id), event text not null, entity_type text, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index if not exists contacts_org_idx on contacts(organization_id);
create index if not exists leads_org_status_idx on leads(organization_id,status);
create index if not exists deals_org_stage_idx on deals(organization_id,stage_id);
create index if not exists tasks_org_assignee_idx on tasks(organization_id,assignee_id);
